func newTrackingLink() unsafe.Pointer { return unsafe.Pointer(new(checkcall.TrackingLink)) }

func newNTrackingLink(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]checkcall.TrackingLink, n)))
}

func ptrTrackingLink(p unsafe.Pointer, c int32) any {
	r := (*checkcall.TrackingLink)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ShipmentMoveID))
	case 5:
		return (*string)(unsafe.Pointer(&r.CarrierID))
	case 6:
		return &r.TokenHash
	case 7:
		return &r.RecipientEmail
	case 8:
		return &r.ExpiresAt
	case 9:
		return &r.RevokedAt
	case 10:
		return &r.LastUsedAt
	case 11:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 12:
		return &r.CreatedAt
	case 13:
		return &r.UpdatedAt
	}
	return nil
}

func valueTrackingLink(p unsafe.Pointer, c int32) any {
	r := (*checkcall.TrackingLink)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.ShipmentMoveID)
	case 5:
		return string(r.CarrierID)
	case 6:
		return r.TokenHash
	case 7:
		if r.RecipientEmail == "" {
			return nil
		}
		return r.RecipientEmail
	case 8:
		return r.ExpiresAt
	case 9:
		if r.RevokedAt == nil {
			return nil
		}
		return *r.RevokedAt
	case 10:
		if r.LastUsedAt == nil {
			return nil
		}
		return *r.LastUsedAt
	case 11:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 12:
		return r.CreatedAt
	case 13:
		return r.UpdatedAt
	}
	return nil
}

